"""Embed numbered native screenshots into a self-contained review HTML."""
import argparse
import base64
import html
import json
from pathlib import Path
import struct

CSS = '\n:root{color-scheme:light;--ink:#243145;--muted:#59677a;--line:#dce3ed;--blue:#315fc1}*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei","Noto Sans CJK SC",sans-serif}button,select{font:inherit;color:inherit}button,select{border:1px solid var(--line);border-radius:6px;background:#fff;min-height:42px;padding:8px 12px}button{cursor:pointer}button:hover{background:#edf3ff}button:disabled{cursor:default;opacity:.45}button[aria-pressed=true]{background:var(--blue);border-color:var(--blue);color:#fff}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #8baef8;outline-offset:3px}header,main{max-width:1140px;margin:auto;padding:20px}header{padding-bottom:12px}h1{font-size:23px;margin:0 0 6px}header p{margin:4px 0;color:var(--muted)}.note{font-size:13px}.toolbar{background:#fff;border:1px solid var(--line);border-radius:8px;padding:12px;margin-bottom:16px}.interactive{display:none}.js .interactive{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.groups{margin-bottom:10px}.navigation{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.navigation label{font-size:13px;color:var(--muted)}select{flex:1;min-width:160px;max-width:100%;width:100%;text-overflow:ellipsis}.counter{font-size:13px;color:var(--muted);white-space:nowrap}.zoom{display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--line);margin-top:12px;padding-top:12px}.key-hint{font-size:12px;color:var(--muted);margin-left:auto}.shot{background:white;border:1px solid var(--line);border-radius:8px;margin:0 0 18px;min-width:0;overflow:hidden}.shot figcaption{padding:18px 20px 14px}.heading{display:flex;align-items:baseline;gap:10px}.number{font:600 14px/1.4 ui-monospace,Consolas,monospace;color:var(--blue)}h2{font-size:18px;margin:0;overflow-wrap:anywhere}.evidence,.caption{font-size:13px;margin:6px 0 0;color:var(--muted)}.evidence{color:#76500f}.image-stage{overflow:auto;max-width:100%;max-height:78vh;min-height:80px;background:#e8edf3;padding:16px;text-align:center;overscroll-behavior:contain}.image-stage img{display:block;margin:auto;max-width:100%;height:auto;background:#fff}.js .image-stage img{max-width:none}.image-meta{margin:0;padding:9px 20px;font-size:12px;color:var(--muted)}[hidden]{display:none!important}details{border-top:1px solid var(--line);padding-top:16px;margin-top:20px}summary{cursor:pointer;font-weight:600}ol{columns:2;column-gap:32px;padding-left:24px}li{break-inside:avoid;margin:8px 0;font-size:14px;overflow-wrap:anywhere}a{color:var(--blue);text-underline-offset:3px}footer{font-size:13px;color:var(--muted);margin-top:20px}.js .shot:target{scroll-margin-top:14px}@media(max-width:600px){header,main{padding:14px}h1{font-size:21px}.toolbar{padding:10px}.groups button{flex:1;padding:8px 5px;font-size:13px}.navigation{display:grid;grid-template-columns:1fr 1fr;gap:8px}.navigation label{grid-column:1/-1}.navigation select{grid-column:1/-1;min-width:0}.counter{grid-column:1/-1;text-align:center}.navigation button{width:100%}.key-hint{display:none}.zoom button{flex:1;padding:8px 5px;font-size:13px}.shot figcaption{padding:14px}.heading{align-items:flex-start;gap:8px}h2{font-size:17px}.image-stage{padding:10px;max-height:72vh}.image-meta{padding:8px 14px}ol{columns:1}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n'
JS = "\n(()=>{'use strict';\nconst shots=Array.from(document.querySelectorAll('.shot')),select=document.getElementById('shot-select');\nlet group='all',current=shots[0],zoom='fit';\nconst allowed=()=>shots.filter(s=>group==='all'||s.dataset.group===group);\nfunction applyZoom(){const img=current.querySelector('img'),stage=current.querySelector('.image-stage');if(!img.naturalWidth)return;const available=stage.clientWidth-(innerWidth<=600?20:32);img.style.width=(zoom==='actual'?img.naturalWidth:zoom==='double'?img.naturalWidth*2:Math.min(available,img.naturalWidth*2))+'px';img.style.height='auto';}\nfunction show(id,focus=false){const next=shots.find(s=>s.dataset.id===id);if(!next)return;current=next;shots.forEach(s=>s.hidden=s!==current);select.value=id;const list=allowed(),at=list.indexOf(current);document.getElementById('counter').textContent=(at+1)+' / '+list.length+' · '+id;document.getElementById('previous').disabled=at===0;document.getElementById('next').disabled=at===list.length-1;document.querySelectorAll('[data-zoom]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.zoom===zoom)));applyZoom();current.querySelector('.image-stage').scrollTo(0,0);if(focus)current.querySelector('h2').focus({preventScroll:true});}\nfunction changeGroup(value){group=value;document.querySelectorAll('[data-group-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.groupFilter===group)));Array.from(select.options).forEach(o=>{o.hidden=group!=='all'&&o.dataset.group!==group;});show(allowed().includes(current)?current.dataset.id:allowed()[0].dataset.id);}\nfunction step(delta){const list=allowed(),at=list.indexOf(current),next=list[at+delta];if(next)show(next.dataset.id);}\nselect.addEventListener('change',()=>show(select.value));\ndocument.getElementById('previous').addEventListener('click',()=>step(-1));document.getElementById('next').addEventListener('click',()=>step(1));\ndocument.querySelectorAll('[data-group-filter]').forEach(b=>b.addEventListener('click',()=>changeGroup(b.dataset.groupFilter)));\ndocument.querySelectorAll('[data-zoom]').forEach(b=>b.addEventListener('click',()=>{zoom=b.dataset.zoom;show(current.dataset.id);}));\ndocument.querySelectorAll('[data-shot]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const id=a.dataset.shot,shot=shots.find(s=>s.dataset.id===id);if(group!=='all'&&shot.dataset.group!==group)changeGroup(shot.dataset.group);show(id,true);document.getElementById('directory').open=false;current.scrollIntoView({block:'start'});}));\ndocument.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowRight'?1:-1);}});\nwindow.addEventListener('resize',applyZoom);shots.forEach(s=>s.querySelector('img').addEventListener('load',()=>{if(s===current)applyZoom();}));\ndocument.documentElement.classList.add('js');show('N01');\n})();\n"

TITLES = {
 "N01": ("冲突版本与实际来源对照", "按插件对照携带的版本，共享环境与实际加载路径单独列出。"),
 "N02": ("配置试运行设置与超时", "选择出厂设置或当前插件设置，并调整单次运行时间上限。"),
 "N03": ("配置缩减次数上限", "沿用首次试运行的设置与超时；次数预算包含最终复验。"),
 "N04": ("明确确认的是故障复现", "Failure reproduced 表示保留的组合再次失败，不表示插件兼容。"),
 "N05": ("历史与当前环境对比", "对照插件更新前后的版本、依赖和实际导入来源。"),
 "N06": ("查看历史快照", "明确显示归档身份与捕获时间，禁止直接对旧记录启动试运行。"),
 "N07": ("导出可分享支持包", "报告、扫描、逐次结果与摘要对应同一记录；默认替换本地路径前缀。"),
}

def main():
 p=argparse.ArgumentParser();p.add_argument('--captures',type=Path,required=True);p.add_argument('--version',required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
 captures=json.loads((a.captures/'metadata.json').read_text())
 options=[];links=[];figures=[]
 for item in captures:
  ident=item['file'][:3];title,caption=TITLES[ident];raw=(a.captures/item['file']).read_bytes();width,height=struct.unpack('>II',raw[16:24]);encoded=base64.b64encode(raw).decode()
  options.append(f'<option value="{ident}" data-group="native">{ident} · {html.escape(title)}</option>')
  links.append(f'<a href="#shot-{ident}" data-shot="{ident}">{ident} · {html.escape(title)}</a>')
  figures.append(f'<figure class="shot" id="shot-{ident}" data-id="{ident}" data-group="native"><figcaption><div class="heading"><span class="number">{ident}</span><h2 tabindex="-1">{html.escape(title)}</h2></div><p class="caption">{html.escape(caption)}</p><p class="evidence">实际 Blender 4.5.15 界面 · 生成的测试插件，非社区真实案例 · 待审</p></figcaption><div class="image-stage"><img src="data:image/png;base64,{encoded}" width="{width}" height="{height}" alt="{html.escape(title)}"></div><p class="image-meta">{width} × {height} px · 仅保留我们的面板或对话框</p></figure>')
 title='AddonScope '+a.version+' · 迭代界面审阅'
 document=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>{title}</title><style>{CSS}</style></head><body><header><h1>{title}</h1><p>{len(captures)} 张新版原生界面截图，按编号逐项审阅。</p><p class="note">这轮新增版本对照、当前插件设置快照和实时试验进度。所有诊断仍在 Blender 内查看。本 HTML 仅是截图审阅容器，图片已内嵌。</p></header><main><div class="toolbar interactive" id="controls"><div class="groups"><button data-group-filter="all" aria-pressed="true">新版插件 {len(captures)} 张</button></div><div class="navigation"><label for="shot-select">选择编号</label><select id="shot-select">{''.join(options)}</select><button id="previous">上一张</button><button id="next">下一张</button><span id="counter" aria-live="polite"></span></div><div class="zoom"><button data-zoom="fit" aria-pressed="true">适应宽度</button><button data-zoom="actual" aria-pressed="false">原尺寸</button><button data-zoom="double" aria-pressed="false">放大 2 倍</button></div></div><details id="directory" class="interactive"><summary>截图目录</summary><nav>{''.join(links)}</nav></details><div id="shots">{''.join(figures)}</div></main><script>{JS}</script></body></html>'''
 a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(document);print(a.output)

if __name__=='__main__':main()
